  insert into public.curriculum_topics(module_id,code,title,kind,lesson_text,worked_solution,diagnostic_quiz,antx_reward_trigger,is_complete,sort_order) values (module_id,'mechanics_2','Kinematics, Motion Graphs & Linear Acceleration','lesson','Kinematics, Motion Graphs & Linear Acceleration: Connect gradient and area to motion: v = Δs/Δt, a = Δv/Δt, and v² = u² + 2as. Read gradients and areas from displacement-time and velocity-time graphs. Apply the idea to a practical Caribbean context such as transport, weather, coastal observation, household energy use, public safety, or community technology. Work in SI units and explain each step.','1. List the known values with units. 2. Select the governing relationship for Kinematics, Motion Graphs & Linear Acceleration. 3. Convert units before substitution. 4. Rearrange the formula algebraically if needed. 5. Substitute, calculate, state the unit, and check the magnitude against the physical context.','[{"prompt": "A learner is checking Kinematics, Motion Graphs & Linear Acceleration. Which first action is best?", "options": ["List known values and units", "Skip unit conversion", "Guess the formula", "Round before calculating"], "answer": 0, "feedback": "Correct: identify the data and units before choosing a relationship."}, {"prompt": "Which habit improves a Kinematics, Motion Graphs & Linear Acceleration calculation?", "options": ["Show substitution and a unit check", "Hide intermediate steps", "Mix grams with kilograms", "Ignore the diagram"], "answer": 0, "feedback": "Correct: visible substitution and units make the reasoning auditable."}, {"prompt": "What earns the Kinematics, Motion Graphs & Linear Acceleration ANTX micro-drop?", "options": ["A correct explained attempt and diagnostic check", "Opening the lesson only", "Buying a reward", "Submitting random answers"], "answer": 0, "feedback": "Correct: rewards follow verified academic effort only."}]'::jsonb,'ANTX micro-drop: +5 closed-loop learning points after compl