  insert into public.curriculum_topics(module_id,code,title,kind,lesson_text,worked_solution,diagnostic_quiz,antx_reward_trigger,is_complete,sort_order) values (module_id,'atomic_nuclear_4','Nuclear Fission, Fusion & Mass-Energy Equivalence','lesson','Nuclear Fission, Fusion & Mass-Energy Equivalence: Fission splits heavy nuclei; fusion joins light nuclei. Small mass changes release E = mc², so safe control and containment matter. Apply the idea to a practical Caribbean context such as transport, weather, coastal observation, household energy use, public safety, or community technology. Work in SI units and explain each step.','1. List the known values with units. 2. Select the governing relationship for Nuclear Fission, Fusion & Mass-Energy Equivalence. 3. Convert units before substitution. 4. Rearrange the formula algebraically if needed. 5. Substitute, calculate, state the unit, and check the magnitude against the physical context.','[{"prompt": "A learner is checking Nuclear Fission, Fusion & Mass-Energy Equivalence. Which first action is best?", "options": ["List known values and units", "Skip unit conversion", "Guess the formula", "Round before calculating"], "answer": 0, "feedback": "Correct: identify the data and units before choosing a relationship."}, {"prompt": "Which habit improves a Nuclear Fission, Fusion & Mass-Energy Equivalence calculation?", "options": ["Show substitution and a unit check", "Hide intermediate steps", "Mix grams with kilograms", "Ignore the diagram"], "answer": 0, "feedback": "Correct: visible substitution and units make the reasoning auditable."}, {"prompt": "What earns the Nuclear Fission, Fusion & Mass-Energy Equivalence ANTX micro-drop?", "options": ["A correct explained attempt and diagnostic check", "Opening the lesson only", "Buying a reward", "Submitting random answers"], "answer": 0, "feedback": "Correct: rewards follow verified academic effort only."}]'::jsonb,'ANTX micro-drop: +5 closed-loop learning points after completing the Nuclear Fission, Fusion & Mass-Energy Equivalence diagnostic and reflection.',true,4) on conflict (module_id,code) do update set title=excluded.title,lesson_text=excluded.lesson_text,worked_solution=excluded.worked_solution,diagnostic_quiz=excluded.diagnostic_quiz,antx_reward_trigger=excluded.antx_reward_trigger,is_complete=true returning id into topic_id;
